class Resource extends Base {
 mount(){this.rows??=[['mira','Mira Shah','Design','Active',2400],['elio','Elio Martin','Engineering','Active',3200],['noor','Noor Haddad','Research','Review',1800],['kai','Kai Tanaka','Design','Active',2100],['ada','Ada Mensah','Operations','Away',1950],['luca','Luca Rossi','Engineering','Active',3600],['inez','Inez Costa','Research','Review',2200],['sana','Sana Patel','Design','Active',2750],['leo','Leo Andersen','Operations','Away',1600],['mina','Mina Park','Engineering','Active',3400],['omar','Omar Ali','Research','Review',2300],['faye','Faye Wilson','Design','Active',2450]].map(([id,name,role,status,amount])=>({id,name,role,status,amount}));this.selected=new Set(this.selected||[]);this.page=0;this.sortKey='name';this.direction=1;this.query='';this.render(`<section class="panel workspace"><header class="row between"><div><span class="label">TEAM DIRECTORY</span><h2>People, in good order.</h2></div><button class="secondary" data-csv>Export CSV ↗</button></header><div class="toolbar"><label><span>⌕</span><input type="search" placeholder="Search people, roles or status…" aria-label="Search records"/></label><span data-selected aria-live="polite"></span></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="Select current page" data-all/></th>${[['name','Person'],['role','Role'],['status','Status'],['amount','Allocation']].map(([key,label])=>`<th data-column="${key}" scope="col"><button data-sort="${key}">${label}<span>↕</span></button></th>`).join('')}<th><span class="sr-only">Open record</span></th></tr></thead><tbody></tbody></table></div><footer class="row between"><span data-page></span><div class="row"><button class="icon" data-prev aria-label="Previous page">←</button><button class="icon" data-next aria-label="Next page">→</button></div></footer><p class="hint" data-open aria-live="polite">Choose a person to inspect their record.</p></section>`,`.workspace{padding:26px;min-height:490px;background:var(--bg)}header{gap:20px;flex-wrap:wrap}h2{font:400 clamp(24px,4vw,32px) Georgia;margin-top:10px}header button{font-size:11px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:18px;margin:25px 0 17px}.toolbar label{display:flex;align-items:center;gap:9px;width:330px;max-width:100%;border:1px solid var(--line);border-radius:8px;padding:0 11px;background:var(--panel)}.toolbar label>span{font-size:20px;color:var(--muted)}.toolbar input{padding-left:0;background:none;border:0;outline:none;width:100%;font-size:11px}.toolbar>span{font-size:10px;color:var(--muted);white-space:nowrap}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:12px;min-width:480px}th{text-align:left;padding:12px 11px;border-bottom:1px solid var(--line);font-size:10px;font-weight:500;color:var(--muted);background:var(--panel)}th:first-child,td:first-child{width:42px;text-align:center}th>button{background:none;border:0;display:flex;gap:12px;align-items:center;padding:3px 0;color:inherit;font-size:10px}th[aria-sort]{color:var(--accent)}th>button>span{font-size:12px;opacity:.6}td{padding:12px 11px;border-bottom:1px solid var(--line)}tr:last-child td{border-bottom:0}tbody tr.selected{background:color-mix(in srgb,var(--accent) 6%,transparent)}.person{display:flex;align-items:center;gap:10px;white-space:nowrap}.avatar{display:grid;place-items:center;width:29px;height:29px;border-radius:9px;color:var(--accent);background:#a6b79115;font-size:9px}.person strong{font-size:11px;font-weight:500}.person small{display:block;font-size:9px;color:var(--muted);margin-top:4px}.status{font-size:9px;display:inline-flex;align-items:center;gap:5px}.status::before{content:'';width:4px;height:4px;border-radius:50%;background:currentColor}.status.Active{color:#9ebf9c}.status.Review{color:#ceb78b}.status.Away{color:#9cabbc}.open{border:0;background:none;color:var(--muted);font-size:18px;padding:5px}footer{padding:17px 0;font-size:10px;color:var(--muted)}[data-open]{padding-top:10px;border-top:1px solid var(--line);font-size:10px}@media(max-width:480px){.workspace{padding:20px 14px}.toolbar{flex-wrap:wrap;gap:9px}.toolbar label{width:100%}header button{font-size:10px}h2{font-size:25px}}`);this.listen(this.$('input[type=search]'),'input',e=>{this.query=e.target.value;this.page=0;this.draw();});this.listen(this.shadowRoot,'click',e=>{const sort=e.target.closest('[data-sort]');if(sort){this.direction=this.sortKey===sort.dataset.sort?-this.direction:1;this.sortKey=sort.dataset.sort;this.draw();}if(e.target.closest('[data-prev]')){this.page--;this.draw();}if(e.target.closest('[data-next]')){this.page++;this.draw();}if(e.target.closest('[data-csv]'))this.exportCSV();const open=e.target.closest('[data-open-row]');if(open){const row=this.rows.find(r=>String(r.id)===open.dataset.openRow);this.$('[data-open]').textContent=`${row.name} · ${row.role} · ${row.status} · Allocation ${new Intl.NumberFormat().format(row.amount)}`;this.emit('row-open',{row:{...row}});}});this.listen(this.shadowRoot,'change',e=>{if(e.target.matches('[data-row]')){const id=e.target.dataset.row;e.target.checked?this.selected.add(id):this.selected.delete(id);}else if(e.target.matches('[data-all]'))for(const row of this.visibleRows)e.target.checked?this.selected.add(String(row.id)):this.selected.delete(String(row.id));else return;this.draw();this.emit('selection-change',{ids:[...this.selected]});});this.draw();}
 filtered(){const q=this.query.toLowerCase().trim();return this.rows.filter(r=>`${r.name} ${r.role} ${r.status}`.toLowerCase().includes(q)).sort((a,b)=>{const x=a[this.sortKey],y=b[this.sortKey];return(typeof x==='number'?x-y:String(x).localeCompare(String(y)))*this.direction;});}
 draw(){const rows=this.filtered(),size=this.number('count',5,3,10),pages=Math.max(1,Math.ceil(rows.length/size));this.page=clamp(this.page,0,pages-1);this.visibleRows=rows.slice(this.page*size,(this.page+1)*size);this.$('tbody').innerHTML=this.visibleRows.length?this.visibleRows.map(row=>`<tr class="${this.selected.has(String(row.id))?'selected':''}"><td><input type="checkbox" data-row="${escape(row.id)}" aria-label="Select ${escape(row.name)}" ${this.selected.has(String(row.id))?'checked':''}/></td><td><div class="person"><span class="avatar" aria-hidden="true">${escape(row.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><span><strong>${escape(row.name)}</strong><small>${escape(row.id)}</small></span></div></td><td>${escape(row.role)}</td><td><span class="status ${['Active','Review','Away'].includes(row.status)?row.status:''}">${escape(row.status)}</span></td><td>${new Intl.NumberFormat().format(Number(row.amount)||0)}</td><td><button class="open" data-open-row="${escape(row.id)}" aria-label="Open ${escape(row.name)}">↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No records match your search.</td></tr>';this.$$('[data-column]').forEach(th=>{if(th.dataset.column===this.sortKey)th.setAttribute('aria-sort',this.direction===1?'ascending':'descending');else th.removeAttribute('aria-sort');});this.$('[data-selected]').textContent=`${this.selected.size} selected`;this.$('[data-page]').textContent=rows.length?`${this.page*size+1}–${Math.min((this.page+1)*size,rows.length)} of ${rows.length} people`:'0 results';this.$('[data-prev]').disabled=this.page===0;this.$('[data-next]').disabled=this.page>=pages-1;const checked=this.visibleRows.filter(r=>this.selected.has(String(r.id))).length;this.$('[data-all]').checked=this.visibleRows.length>0&&checked===this.visibleRows.length;this.$('[data-all]').indeterminate=checked>0&&checked<this.visibleRows.length;}
 configured(name){if(name==='count'){this.page=0;this.draw();}}
 exportCSV(){const quote=value=>{let text=String(value??'');if(/^[=+\-@]/.test(text))text="'"+text;return'"'+text.replaceAll('"','""')+'"';};const rows=[['Name','Role','Status','Allocation'],...this.filtered().map(r=>[r.name,r.role,r.status,r.amount])];downloadBlob(rows.map(row=>row.map(quote).join(',')).join('\r\n'),'team-directory.csv','text/csv;charset=utf-8');}
}
